style.css:
@-moz-document domain("hlamer.ru"), domain("krasview.ru") {
.wrapper {
    height: 100% !important;
}

.video-block-top-ad {
    display: none !important;
}
#video-side {
    display: none !important;
}

#video-container {
    width: 100% !important;
    max-width: none !important;
    float: none !important;
}

#html5-container,
#html5-container .mejs-container,
#html5-container #mep_0,
#html5-container .mejs-inner,
#html5-container .mejs-mediaelement,
#video-flash {
    width: 100% !important;
    max-width: none !important;
}

#video-flash {
    height: auto !important;
}

#video-container {
    width: 100% !important;
    max-width: none !important;
    float: none !important;
}

#html5-container {
    width: 100% !important;
    height: auto !important;
    aspect-ratio: 16 / 9 !important;
}

#mep_0 {
    width: 100% !important;
    height: 100% !important;
}

.mejs-mediaelement,
#video-flash {
    width: 100% !important;
    height: 100% !important;
}
#video-comments,
#video-comments .block,
#video-comments .block-content {
    width: 99% !important;
    max-width: none !important;
}
}
